using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class HonorédeBalzac
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il existe un lien secret entre toutes les femmes, comme entre tous les prêtres d'une même religion. Elles se haïssent, mais elles se protégent.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Nous sommes allés chercher de la laine et nous allons revenir tondus.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L'amour est la seule passion qui ne souffre ni passé ni avenir.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La joie ne peut éclater que parmi les gens qui se sentent égaux.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Nous avons tous la prétention de souffrir beaucoup plus que les autres.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le despotisme fait illégalement de grandes choses, la liberté ne se donne même pas la peine d'en faire légalement de très petites.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’écrivain doit être familiarisé avec tous les effets, toutes les natures. Il est obligé d’avoir en lui je ne sais quel miroir concentrique où, suivant sa fantaisie, l’univers vient se réfléchir.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Mais, sachez-le bien, à peine avez-vous fait un pas vers le tapis vert, déjà votre chapeau ne vous appartient pas plus que vous ne vous appartenez à vous-même : vous êtes au jeu, vous, votre fortune, votre coiffe, votre canne et votre manteau.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Vouloir nous brûle et Pouvoir nous détruit; mais SAVOIR laisse notre faible organisation dans un perpétuel état de calme.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La pensée est la clef de tous les trésors, elle procure les joies de l'avare sans en donner les soucis.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le journalisme, vois-tu, c'est la religion des sociétés modernes, et il y a progrès.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Je dus [...] aller voir des hommes d'État, [...] les séduire, eux, leurs femmes, leurs valets, leurs chiens [...].", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les orphelins recueillis par la charité publique ont au moins pour avenir le champ de bataille, pour père le gouvernement ou le procureur du roi, pour refuge un hospice. Moi, je n'avais rien !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Devenant tout à coup physiologiste par instinct, il rendait compte des ressemblances animales inscrites sur les figures humaines, par des analogies primordiales et par le mouvement ascendant de la création.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le sot n’est-il pas celui qui ne justifie pas la bonne opinion qu’il prend de lui-même ?", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Religion veut dire LIEN, et certes le culte, ou autrement dit la religion exprimée, constitue la seule force qui puisse relier les Espèces sociales et leur donner une forme durable.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Si la lumière est le premier amour de la vie, l'amour n'est-il pas la lumière du cœur ?", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La gloire est le soleil des morts, de ton vivant, tu seras malheureux comme tout ce qui fut grand, et tu ruineras tes enfants.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Plus nos lois tendront à une impossible égalité, plus nous nous en écarterons par les mœurs.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’esprit français, le plus vif, le plus acéré de tous les instruments intelligentiels", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le journaliste est une pensée en marche comme le soldat en guerre", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La seule épigramme permise à la Misère est d' obliger la Justice et la Bienfaisance à des dénis injustes. Quand les malheureux ont convaincu la Société de mensonge, ils se rejettent plus vivement dans le sein de Dieu.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Où en étais-je ? dit le colonel avec la naïveté d’un enfant ou d’un soldat, car il y a souvent de l’enfant dans le vrai soldat, et presque toujours du soldat chez l’enfant, surtout en France.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le malheur est une espèce de talisman dont la vertu consiste à corroborer notre constitution primitive : il augmente la défiance et la méchanceté chez certains hommes, comme il accroît la bonté de ceux qui ont un cœur excellent.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il existe dans notre société trois hommes, le Prêtre, le Médecin et l'Homme de justice, qui ne peuvent pas estimer le monde. Ils ont des robes noires, peut-être parce qu'ils portent le deuil de toutes les vertus, de toutes les illusions.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "[...] Toutes les horreurs que les romanciers croient inventer sont toujours au-dessous de la vérité.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les mythes modernes sont encore moins compris que les mythes anciens, quoique nous soyons dévorés par les mythes.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’amour-propre est un escroc qui ne manque jamais sa dupe.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le génie procède de deux manières : ou il prend son bien comme Napoléon et Molière aussitôt qu’il le voit, ou il attend qu’on le vienne chercher quand il s’est patiemment révélé.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Les lois sont des toiles d’araignées à travers lesquelles passent les grosses mouches et où restent les petites.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Dans ce produit bizarre, vous eussiez reconnu l'actionnaire par excellence, croyant à toutes les nouvelles que la presse périodique baptise de son encre, et qui a tout dit en disant : Lisez le journal !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En France, ce qu’il y a de plus national, est la vanité. La masse des vanités blessées y a donné soif d’égalité.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Privilége semblable à celui de la noblesse, la beauté ne se peut acquérir, elle est partout reconnue, et vaut souvent plus que la fortune et le talent, elle n’a besoin que d’être montrée pour triompher, on ne lui demande que d’exister.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Quand un artiste a le malheur d’être plein de la passion qu’il veut exprimer, il ne saurait la peindre, car il est la chose même au lieu d’en être l’image. L’art procède du cerveau et non du cœur. Quand votre sujet vous domine, vous en êtes l’esclave et non le maître.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’épicier est entraîné vers son commerce par une force attractive égale a la force de répulsion qui en éloigne les artistes.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Il lisait d’ailleurs beaucoup, il se donnait cette profonde et sérieuse instruction que l’on ne tient que de soi-même, et à laquelle tous les gens de talent se sont livrés entre vingt et trente ans.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Néanmoins il n’existe pas de grand talent sans une grande volonté. Ces deux forces jumelles sont nécessaires à la construction de l’immense édifice d’une gloire. Les hommes d’élite maintiennent leur cerveau dans les conditions de la production, comme jadis un preux avait ses armes toujours en état.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "En conceptions bizarres, l’imagination des femmes va plus loin que celle des hommes, témoin le Frankenstein de mistress Shelley, le Leone Leoni de George Sand, les œuvres d’Anne Radcliffe et le Nouveau Prométhée de Camille Maupin.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La femme porte le désordre dans la société par la passion.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’impression est aux manuscrits ce que le théâtre est aux femmes elle met en lumière les beautés et les défauts ; elle tue aussi bien qu’elle fait vivre ; une faute saute alors aux yeux aussi vivement que les belles pensées.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le roman, qui veut le sentiment, le style et l’image, est la création moderne la plus immense. Il succède à la comédie qui, dans les mœurs modernes, n’est plus possible avec ses vieilles lois.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Le Poète qui semble ne rien faire et qui néanmoins règne sur l’Humanité quand il a su la peindre.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Bettina mourante inocula donc l’amour à sa sœur, elle lui communiqua cette lèpre de l’âme.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Ni lord Byron, ni Goethe, ni Walter Scott, ni Cuvier, ni l’inventeur ne s’appartiennent, ils sont les esclaves de leur idée ; et cette puissance mystérieuse est plus jalouse qu’une femme, elle les absorbe, elle les fait vivre et les tue à son profit.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "A Paris, un nom devient une propriété commerciale, et finit par constituer une sorte de noblesse d’enseigne.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "L’opinion d’un artiste doit être la foi dans les œuvres… et son seul moyen de succès, le travail quand la nature lui a donné le feu sacré.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Mon père m'a donné un cœur, mais vous l'avez fait battre.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac à Eve Hanska, 19 octobre 1834 : Le dernier roman de Mme Dudevant est un conseil donné aux maris, qui gênent leurs femmes, de se tuer pour les laisser libres...", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "La Divine comédie est l'histoire de l'homme qui a vécu, 'La Comédie humaine' est l'histoire de l'homme qui vit.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Car les héros de l’Iliade ne vont qu’à votre cheville, ô Vautrin, ô Rastignac, ô Birotteau [...] et vous, ô Honoré de Balzac, vous le plus héroïque, le plus singulier, le plus romantique et le plus poétique parmi tous les personnages que vous avez tirés de votre sein !", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Voilà l'œuvre qu'il nous laisse, œuvre haute et solide, robuste entassement d'assises de granit, monument!œuvre du haut de laquelle resplendira désormais sa renommée. Les grands hommes font leur propre piédestal, l'avenir se charge de la statue.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Shakespeare seul a enfanté une humanité aussi large et aussi vivante.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Henri IV a conquis son royaume ville à ville. M. de Balzac a conquis son public maladif infirmités par infirmités (aujourd'hui les femmes de trente ans, demain celles de cinquante, après-demain les chlorotiques, dans ''Claës'' les contrefaits). Nulle part il est question de santé.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "J'admire comme les pensées de Balzac sont cosmologiquement justes. Telle est la part de sa forte tête dans ses créations qu'il entre dans les lieux communs et les rend vrais.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac, c’est vous, c’est moi. En Balzac, je m’instruis beaucoup, non pas dans le vocabulaire des idées, mais dans celui des choses.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Balzac n’est pas un précurseur. Il est le créateur du monde moderne. C’est pourquoi tout jeune auteur d’aujourd’hui doit passer par lui.", Author = "Honoré de Balzac" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Honoré_de_Balzac", Text = "Chacun sait que ce gros homme entendait faire une œuvre de défense et illustration des défenses sociales, voire de l'ordre moral, et qu'il a dressé, en fait, le plus formidable acte d'accusation qui ait jamais été lancé contre une civilisation.", Author = "Honoré de Balzac" },
        };
    }
}
